PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    MotorOn : BOOL := FALSE;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := NOT EStop, PT := T#1s);

IF NOT EStop THEN
    Motor := FALSE;
    MotorOn := FALSE;
ELSIF Start AND NOT Stop AND NOT MotorOn THEN
    Motor := TRUE;
    MotorOn := TRUE;
ELSIF Stop THEN
    Motor := FALSE;
    MotorOn := FALSE;
END_IF;

Motor := SafetyTimer.Q AND Motor;

END_PROGRAM

