PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    prev_PumpIn : BOOL := FALSE;
    prev_ValveOut : BOOL := FALSE;
    LevelLowLimit : INT := 10;
    LevelHighLimit : INT := 90;
END_VAR

// Check for safety condition
IF Level >= LevelHighLimit AND prev_PumpIn THEN
    PumpIn := FALSE;
END_IF;

// Update outputs based on level
IF Level <= LevelLowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSIF Level >= LevelHighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

// Assign outputs
prev_PumpIn := PumpIn;
prev_ValveOut := ValveOut;
END_PROGRAM

