PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    PumpPrev : BOOL := FALSE;
    ValvePrev : BOOL := FALSE;
    HystLow : INT := 10;
    HystHigh : INT := 90;
END_VAR

// Check if the pump state changed
IF PumpPrev <> PumpIn THEN
    // If it did, update the previous state
    PumpPrev := PumpIn;
END_IF;

// Check if the valve state changed
IF ValvePrev <> ValveOut THEN
    // If it did, update the previous state
    ValvePrev := ValveOut;
END_IF;

// Check if the level is at or above the high limit
IF Level >= HystHigh THEN
    // Turn off the pump and open the valve
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    // Check if the level is at or below the low limit
    IF Level <= HystLow THEN
        // Turn on the pump and close the valve
        PumpIn := TRUE;
        ValveOut := FALSE;
    ELSE
        // Otherwise, keep the previous states
        PumpIn := PumpPrev;
        ValveOut := ValvePrev;
    END_IF;
END_IF;
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
