    PumpPrev : BOOL := FALSE;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := NOT Level >= 90 AND PumpIn, PT := T#1s);

PumpIn := NOT Level >= 90 AND (Level <= 10 OR (NOT PumpPrev AND Level > 10));
ValveOut := Level >= 90;

PumpPrev := PumpIn;
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    PumpPrev : BOOL := FALSE;
    ValvePrev : BOOL := FALSE;
    PumpTimer : TON;
    ValveTimer : TON;
END_VAR

// Check if the level is within the safe operating range
IF NOT (Level >= 90 AND PumpIn) THEN
    // Control the inlet pump based on the hysteresis limits
    IF Level <= 10 THEN
        PumpIn := TRUE;
    ELSIF Level >= 90 THEN
        PumpIn := FALSE;
    ELSE
        PumpIn := PumpPrev;
    END_IF;

    // Control the outlet valve based on the high limit
    IF Level >= 90 THEN
        ValveOut := TRUE;
    ELSE
        ValveOut := FALSE;
    END_IF;

    // Update previous states for safety check
    PumpPrev := PumpIn;
    ValvePrev := ValveOut;
ELSE
    // Safety case: stop the pump if the level is at or above 90%
    PumpIn := FALSE;
    ValveOut := TRUE;
    PumpPrev := FALSE;
    ValvePrev := TRUE;
END_IF;

// Reset timers if outputs change
IF PumpIn <> PumpPrev THEN
    PumpTimer(IN := TRUE, PT := T#1s);
ELSE
    PumpTimer(IN := FALSE);
END_IF;

IF ValveOut <> ValvePrev THEN
    ValveTimer(IN := TRUE, PT := T#1s);
ELSE
    ValveTimer(IN := FALSE);
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    prev_PumpIn : BOOL := FALSE;
    prev_ValveOut : BOOL := FALSE;
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PumpTimer : TON;
END_VAR

// Check if the pump should be turned on or off based on the hysteresis
IF Level <= LowLimit THEN
    PumpIn := TRUE;
ELSIF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := prev_PumpIn;
    ValveOut := FALSE;
END_IF;

// Update previous values
prev_PumpIn := PumpIn;
prev_ValveOut := ValveOut;

// Ensure the pump does not run when the level is at or above the high limit
IF Level >= HighLimit THEN
    PumpIn := FALSE;
END_IF;

END_PROGRAM

PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    DoorA_Opened : BOOL := FALSE;
    DoorB_Opened : BOOL := FALSE;
    T_A : TON;
    T_B : TON;
END_VAR

T_A(IN := OpenA_Cmd AND NOT DoorB_Opened, PT := T#1s);
T_B(IN := OpenB_Cmd AND NOT DoorA_Opened, PT := T#1s);

DoorA := T_A.Q AND NOT DoorB_Opened;
DoorB := T_B.Q AND NOT DoorA_Opened;

IF T_A.Q THEN
    DoorA_Opened := TRUE;
ELSE
    DoorA_Opened := FALSE;
END_IF;

IF T_B.Q THEN
    DoorB_Opened := TRUE;
ELSE
    DoorB_Opened := FALSE;
END_IF;
END_PROGRAM

