PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    DoorA_Open : BOOL := FALSE;
    DoorB_Open : BOOL := FALSE;
    PriorityTimer : TON;
END_VAR

// Check if both doors are requested to open simultaneously
IF OpenA_Cmd AND OpenB_Cmd THEN
    // Assign priority to Door A
    DoorA := TRUE;
    DoorB := FALSE;
ELSIF OpenA_Cmd THEN
    // Only Door A is requested to open
    IF NOT DoorB_Open THEN
        DoorA := TRUE;
        DoorB := FALSE;
    ELSE
        DoorA := FALSE;
        DoorB := FALSE;
    END_IF;
ELSIF OpenB_Cmd THEN
    // Only Door B is requested to open
    IF NOT DoorA_Open THEN
        DoorA := FALSE;
        DoorB := TRUE;
    ELSE
        DoorA := FALSE;
        DoorB := FALSE;
    END_IF;
ELSE
    // Neither door is requested to open
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;

// Update the state based on the priority
DoorA := DoorA AND NOT DoorB;
DoorB := DoorB AND NOT DoorA;

END_PROGRAM

PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    Running : BOOL := FALSE;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := NOT (GuardClosed OR Fault), PT := T#1s);

CASE TRUE OF
    StopPB OR SafetyTimer.Q:
        Running := FALSE;
    StartPB AND GuardClosed AND NOT Fault AND NOT Running:
        Running := TRUE;
END_CASE;

Conveyor := Running;
END_PROGRAM

