PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    T_Green_NS, T_.Yellow_NS, T_AllRed : TON;
    T_Green_EW, T_Yellow_EW, T_AllRed_EW : TON;
END_VAR

T_Green_NS(IN := State = 0, PT := T#2s);
T_.Yellow_NS(IN := State = 1, PT := T#1s);
T_AllRed(IN := State = 2, PT := T#1s);
T_Green_EW(IN := State = 3, PT := T#2s);
T_Yellow_EW(IN := State = 4, PT := T#1s);
T_AllRed_EW(IN := State = 5, PT := T#1s);

CASE State OF
    0:
        NS_G := TRUE; NS_Y := FALSE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    1:
        NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    2:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    3:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := TRUE; EW_Y := FALSE; EW_R := FALSE;
    4:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := TRUE; EW_R := FALSE;
    5:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
END_CASE;

NS_G := NS_G AND NOT T_.Yellow_NS.Q AND NOT T_AllRed.Q;
NS_Y := NS_Y AND NOT T_Green_NS.Q AND NOT T_AllRed.Q;
NS_R := NS_R AND NOT T_Green_NS.Q AND NOT T_.Yellow_NS.Q AND NOT T_Green_EW.Q AND NOT T_Yellow_EW.Q AND NOT T_AllRed.EQ;

EW_G := EW_G AND NOT T_.Yellow_EW.Q AND NOT T_AllRed_EW.Q;
EW_Y := EW_Y AND NOT T_Green_EW.Q AND NOT T_AllRed_EW.Q;
EW_R := EW_R AND NOT T_Green_EW.Q AND NOT T_Yellow_EW.Q AND NOT T_Green_NS.Q AND NOT T_Yellow_NS.Q AND NOT T_AllRed.EQ;

IF T_Green_NS.Q THEN
    State := State + 1;
ELSIF T_.Yellow_NS.Q THEN
    State := State + 1;
ELSIF T_AllRed.Q THEN
    State := State + 1;
ELSIF T_Green_EW.Q THEN
    State := State + 1;
ELSIF T_Yellow_EW.Q THEN
    State := State + 1;
ELSIF T_AllRed_EW.Q THEN
    State := State + 1;
END_IF;

State := MOD(State, 6);
END_PROGRAM

