END_VAR

VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR

VAR
    State : INT := 0;
    MoveTimer : TON;
END_VAR

CASE State OF
    0: // At-bottom
        MotorUp := FALSE;
        MotorDown := FALSE;
        IF CallUp AND DoorClosed THEN
            State := 1;
            MoveTimer(IN := TRUE, PT := T#1s);
        END_IF;

    1: // Moving-up
        MotorUp := TRUE;
        MotorDown := FALSE;
        IF AtTop OR NOT CallUp THEN
            MotorUp := FALSE;
            IF AtTop THEN
                State := 2;
            ELSE
                State := 0;
            END_IF;
        ELSIF Not DoorClosed THEN
            MotorUp := FALSE;
            State := 0;
        END_IF;

    2: // At-top
        MotorUp := FALSE;
        MotorDown := FALSE;
        IF CallDown AND DoorClosed THEN
            State := 3;
            MoveTimer(IN := TRUE, PT := T#1s);
        END_IF;

    3: // Moving-down
        MotorUp := FALSE;
        MotorDown := TRUE;
        IF AtBottom OR NOT CallDown THEN
            MotorDown := FALSE;
            IF AtBottom THEN
                State := 0;
            ELSE
                State := 2;
            END_IF;
        ELSIF Not DoorClosed THEN
            MotorDown := FALSE;
            State := 2;
        END_IF;

    ELSE
        State := 0;
END_CASE;

END_PROGRAM

PROGRAM elevator
VAR_INPUT
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR

VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR

VAR
    State : INT := 0;
    MoveTimer : TON;
END_VAR

CASE State OF
    0: // At-bottom
        IF CallUp AND DoorClosed THEN
            State := 1;
            MoveTimer(IN := TRUE, PT := T#3s);
        ELSIF Not CallDown AND Not CallUp THEN
            MoveTimer(IN := FALSE);
        END_IF;

        MotorUp := FALSE;
        MotorDown := FALSE;

    1: // Moving-up
        IF DoorClosed AND NOT AtTop THEN
            MotorUp := TRUE;
            MotorDown := FALSE;
        ELSE
            MotorUp := FALSE;
            MotorDown := FALSE;
            IF AtTop OR (CallDown AND DoorClosed) THEN
                State := 2;
                MoveTimer(IN := TRUE, PT := T#3s);
            END_IF;
        END_IF;

    2: // At-top
        IF CallDown AND DoorClosed THEN
            State := 3;
            MoveTimer(IN := TRUE, PT := T#3s);
        ELSIF Not CallDown AND Not CallUp THEN
            MoveTimer(IN := FALSE);
        END_IF;

        MotorUp := FALSE;
        MotorDown := FALSE;

    3: // Moving-down
        IF DoorClosed AND NOT AtBottom THEN
            MotorUp := FALSE;
            MotorDown := TRUE;
        ELSE
            MotorUp := FALSE;
            MotorDown := FALSE;
            IF AtBottom OR (CallUp AND DoorClosed) THEN
                State := 0;
                MoveTimer(IN := TRUE, PT := T#3s);
            END_IF;
        END_IF;

END_CASE;

MoveTimer(IN := FALSE);

END_PROGRAM

