END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND State = 0 THEN
    State := 1;
ELSIF StartBatch AND State = 1 THEN
    IF Level >= LVL_HIGH THEN
        State := 2;
    ELSE
        FillValve := TRUE;
    END_IF;
ELSIF StartBatch AND State = 2 THEN
    IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
        State := 3;
    ELSE
        Heater := TRUE;
        Agitator := TRUE;
    END_IF;
ELSIF StartBatch AND State = 3 THEN
    IF Timer.TI = PT_REACT THEN
        State := 4;
    ELSE
        Timer(IN := TRUE, PT := T#3s);
        Heater := TRUE;
        Agitator := TRUE;
    END_IF;
ELSIF StartBatch AND State = 4 THEN
    IF Level <= LVL_LOW THEN
        State := 0;
    ELSE
        DrainValve := TRUE;
    END_IF;
ELSIF NOT StartBatch THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

CASE State OF
    0:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    1:
        FillValve := Level < LVL_HIGH;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
