        FillValve := FALSE;
        Heater := Temp < TEMP_SET AND Level >= LIQ_MIN;
        Agitator := Heater;
        DrainValve := FALSE;
    3:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    4:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
