    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

CASE State OF
    0: // Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;
    1: // Fill
        FillValve := TRUE;
        IF Level >= LVL_HIGH THEN
            State := 2;
        END_IF;
    2: // Heat
        Heater := TRUE;
        Agitator := TRUE;
        IF Temp >= TEMP_SET THEN
            State := 3;
        END_IF;
