        Heater := TRUE;
        Agitator := TRUE;
        IF ReactTimer(TIME := T#3s).Q THEN
            State := 4;
        END_IF;
    4: // Drain
        DrainValve := TRUE;
        IF Level <= LVL_LOW THEN
            State := 0;
        END_IF;
END_CASE;

// Prevent filling and draining at the same time
FillValve := FillValve AND NOT DrainValve;
DrainValve := DrainValve AND NOT FillValve;

// Reset timers when entering new states
CASE State OF
    0: FillTimer(IN := FALSE);
       HeatTimer(IN := FALSE);
       ReactTimer(IN := FALSE);
    1: FillTimer(IN := TRUE, PT := T#1s);
    2: HeatTimer(IN := TRUE, PT := T#1s);
