PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    T_HeaterAgitator : TON;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : INT := 3;
END_VAR

CASE State OF
    0: // Idle
        IF StartBatch AND EStop THEN
            State := 1;
        END_IF;

    1: // Fill
        IF NOT EStop AND Level >= LVL_HIGH THEN
            State := 2;
        ELSIF NOT EStop THEN
            FillValve := TRUE;
        ELSE
            FillValve := FALSE;
        END_IF;

    2: // Heat
        IF NOT EStop AND Level >= LIQ_MIN AND Temp >= TEMP_SET THEN
            State := 3;
        ELSIF NOT Estop AND Level >= LIQ_MIN THEN
            Heater := TRUE;
            Agitator := TRUE;
        ELSE
            Heater := FALSE;
            Agitator := FALSE;
        END_IF;

    3: // React
        IF NOT EStop AND Level >= LIQ_MIN THEN
            T_HeaterAgitator(IN := TRUE, PT := T#1s);
            IF T_HeaterAgitator.Q AND T_HeaterAgitator.TI >= PT_REACT THEN
                State := 4;
            END_IF;
        ELSE
            Heater := FALSE;
            Agitator := FALSE;
        END_IF;

    4: // Drain
        IF NOT EStop AND Level <= LVL_LOW THEN
            State := 0;
        ELSIF NOT EStop THEN
            DrainValve := TRUE;
        ELSE
            DrainValve := FALSE;
        END_IF;

ELSE
    State := 0;
END_CASE;

// Safety conditions
FillValve := FALSE;
DrainValve := FALSE;
IF EStop THEN
    State := 0;
    Heater := FALSE;
    Agitator := FALSE;
    FillValve := FALSE;
    DrainValve := FALSE;
ELSIF State = 2 OR State = 3 THEN
    IF Level < LIQ_MIN THEN
        Heater := FALSE;
        Agitator := FALSE;
    END_IF;
ELSIF State = 1 OR State = 4 THEN
    IF Level >= LVL_HIGH OR Level <= LVL_LOW THEN
        FillValve := FALSE;
        DrainValve := FALSE;
    END_IF;
END_IF;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : INT := 3;
    T_FillTimer : TON;
    T_HeatTimer : TON;
    T_ReactTimer : TON;
END_VAR

CASE State OF
    0: // Idle
        IF StartBatch AND NOT EStop THEN
            State := 1;
            T_FillTimer(IN := TRUE, PT := T#3s);
            T_HeatTimer(IN := FALSE);
            T_ReactTimer(IN := FALSE);
        END_IF;

    1: // Fill
        FillValve := TRUE;
        DrainValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;

        IF Level >= LVL_HIGH OR EStop THEN
            State := 2;
            T_FillTimer(IN := FALSE);
            T_HeatTimer(IN := TRUE, PT := T#3s);
        END_IF;

    2: // Heat
        FillValve := FALSE;
        DrainValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;

        IF Temp >= TEMP_SET OR EStop THEN
            State := 3;
            T_HeatTimer(IN := FALSE);
            T_ReactTimer(IN := TRUE, PT := T#3s);
        END_IF;

    3: // React
        FillValve := FALSE;
        DrainValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;

        IF T_ReactTimer.Q THEN
            State := 4;
            T_ReactTimer(IN := FALSE);
        END_IF;

    4: // Drain
        FillValve := FALSE;
        DrainValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;

        IF Level <= LVL_LOW OR EStop THEN
            State := 0;
            T_DrainTimer(IN := FALSE);
        END_IF;
END_CASE;

// Safety checks
IF EStop THEN
    State := 0;
    FillValve := FALSE;
    DrainValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

IF Level < LIQ_MIN THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;
END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    Timer : TON;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSE
    CASE State OF
        0:
            IF StartBatch AND Level >= LIQ_MIN THEN
                State := 1;
                Timer(IN := TRUE, PT := T#0s);
            END_IF;

        1:
            FillValve := Level < LVL_HIGH;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;

            IF Level >= LVL_HIGH AND Timer.Q THEN
                State := 2;
                Timer(IN := TRUE, PT := T#0s);
            END_IF;

        2:
            FillValve := FALSE;
            Heater := Temp < TEMP_SET;
            Agitator := TRUE;
            DrainValve := FALSE;

            IF Temp >= TEMP_SET AND Timer(Q) THEN
                State := 3;
                Timer(IN := TRUE, PT := T#0s);
            END_IF;

        3:
            FillValve := FALSE;
            Heater := Temp < TEMP_SET;
            Agitator := TRUE;
            DrainValve := FALSE;

            IF Timer(Q) AND Timer.TI = PT_REACT THEN
                State := 4;
                Timer(IN := TRUE, PT := T#0s);
            END_IF;

        4:
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := Level > LVL_LOW;

            IF Level <= LVL_LOW AND Timer.Q THEN
                State := 0;
            END_IF;
    END_CASE;
END_IF;

END_PROGRAM

PROGRAM garage
