PROGRAM motor_delay
VAR_INPUT
    StartCmd : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    StartTimer : TON;
    StartHeld : BOOL := FALSE;
    SafetyCheck : BOOL := TRUE;
END_VAR

// Check if the emergency stop is active
SafetyCheck := EStop;

IF NOT SafetyCheck THEN
    // If emergency stop is active, stop the motor and clear the start timer
    Motor := FALSE;
    StartTimer(IN := FALSE);
ELSE
    IF StartCmd AND StartTimer.Q THEN
        // Motor can start
        Motor := TRUE;
    ELSEIF StartCmd AND NOT StartTimer.Q THEN
        // Start the timer if StartCmd is held
        StartTimer(IN := TRUE, PT := T#3s);
    ELSE
        // Stop the motor if StartCmd is released
        Motor := FALSE;
        StartTimer(IN := FALSE);
    END_IF;

    // Check if StartCmd has been held for the entire duration of the timer
    IF StartCmd AND StartTimer.Q THEN
        StartHeld := TRUE;
    ELSE
        StartHeld := FALSE;
    END_IF;
END_IF;

END_PROGRAM

PROGRAM motor_delay
