    HoldCount : INT := 0;
    LastStartCmd : BOOL := FALSE;
END_VAR

Motor := FALSE;

IF NOT EStop THEN
    Motor := FALSE;
    StartTimer(IN := FALSE);
    HoldCount := 0;
ELSE
    IF StartCmd AND NOT LastStartCmd THEN
        StartTimer(IN := TRUE, PT := T#3s);
    END_IF;

    IF StartTimer.Q THEN
        HoldCount := HoldCount + 1;
    ELSE
        HoldCount := 0;
    END_IF;

    IF HoldCount >= 3 THEN
        Motor := TRUE;
    ELSE
        Motor := FALSE;
    END_IF;

    LastStartCmd := StartCmd;
END_IF;

END_PROGRAM

