        Valve := FALSE;
        IF EStop THEN
            State := 0;
        ELSIF StartCycle AND Level < 90 THEN
            State := 1;
        END_IF;

    1: // Filling
        Pump := TRUE;
        Valve := FALSE;
        IF EStop THEN
            State := 0;
        ELSIF Level >= 90 THEN
            State := 2;
        END_IF;

    2: // Draining
        Pump := FALSE;
        Valve := TRUE;
        IF EStop THEN
            State := 0;
        ELSIF Level <= 10 THEN
            State := 0;
        END_IF;
END_CASE;

// Safety conditions
IF Pump AND Valve THEN
    Pump := FALSE;
    Valve := FALSE;
END_IF;

IF Level >= 90 AND Pump THEN
    Pump := FALSE;
END_IF;

IF Level <= 10 AND Valve THEN
    Valve := FALSE;
END_IF;

END_PROGRAM

