PROGRAM two_hand
VAR_INPUT
    LH : BOOL;
    RH : BOOL;
END_VAR

VAR_OUTPUT
    Actuator : BOOL;
END_VAR

VAR
    Armed : BOOL := FALSE;
    Last_LH : BOOL := FALSE;
    Last_RH : BOOL := FALSE;
END_VAR

// Check if both buttons are pressed
IF LH AND RH THEN
    // If not armed, arm it
    IF NOT Armed THEN
        Armed := TRUE;
    END_IF;
ELSE
    // If any button is released, disarm it
    Armed := FALSE;
END_IF;

// Update Actuator only if both buttons are pressed and the control is armed
Actuator := Armed AND LH AND RH;

// Update previous states for next cycle
Last_LH := LH;
Last_RH := RH;
END_PROGRAM

