    RH : BOOL;
END_VAR
VAR_OUTPUT
    Actuator : BOOL;
END_VAR
VAR
    Armed : BOOL := FALSE;
    Prev_LH : BOOL := FALSE;
    Prev_RH : BOOL := FALSE;
    T_BothReleased : TON;
END_VAR

Prev_LH := LH;
Prev_RH := RH;

IF NOT LH AND NOT RH THEN
    T_BothReleased(IN := TRUE, PT := T#1s);
ELSE
    T_BothReleased(IN := FALSE);
end_if;

IF T_BothReleased.Q AND Prev_LH AND Prev_RH THEN
    Armed := TRUE;
ELSIF (LH XOR RH) OR (NOT LH AND NOT RH) THEN
    Armed := FALSE;
END_IF;

Actuator := Armed AND LH AND RH;

END_PROGRAM

