VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
END_VAR

// Edge detection for demand
PrevDemand := Demand;

// Safety check: if EStop is active, turn off all pumps
IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    // Determine if there's been a falling edge in Demand
    IF NOT Demand AND PrevDemand THEN
        // Alternate the lead
        Lead := 1 - Lead;
    END_IF;

    // Assign output based on the lead state and Demand
    IF Demand THEN
        CASE Lead OF
            0: Pump1 := TRUE; Pump2 := FALSE;
            1: Pump1 := FALSE; Pump2 := TRUE;
        ELSE
            Pump1 := FALSE; Pump2 := FALSE;
        END_CASE;
    ELSE
        Pump1 := FALSE; Pump2 := FALSE;
    END_IF;
END_IF;

