VAR
    State : INT := 0;
    MotorOpen : BOOL := FALSE;
    MotorClose : BOOL := FALSE;
    PrevState : INT := -1;
END_VAR

PrevState := State;

CASE State OF
    0: // Idle
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1;
        ELSIF CloseCmd AND NOT (CloseLimit OR Obstruction) THEN
            State := 2;
        END_IF;

    1: // Opening
        IF OpenLimit THEN
            State := 0;
        ELSEIF Obstruction OR CloseCmd THEN
            State := 0;
        END_IF;

    2: // Closing
        IF CloseLimit THEN
            State := 0;
        ELSIF Obstruction OR OpenCmd THEN
            State := 0;
        END_IF;
END_CASE;

// Apply output
CASE State OF
    1: // Opening
        MotorOpen := TRUE;
        MotorClose := FALSE;
    2: // Closing
        MotorOpen := FALSE;
        MotorClose := TRUE;
    ELSE
        MotorOpen := FALSE;
        MotorClose := FALSE;
    END_CASE;

// Reset motor outputs on state change
IF PrevState <> State THEN
    MotorOpen := FALSE;
    MotorClose := FALSE;
END_IF;
END_PROGRAM

