    State : INT := 0;
    OpeningTimer, ClosingTimer : TON;
END_VAR

CASE State OF
    0: // Idle
        MotorOpen := FALSE;
        MotorClose := FALSE;
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1;
        ELSIF CloseCmd AND NOT (CloseLimit OR Obstruction) THEN
            State := 2;
        END_IF;

    1: // Opening
        MotorOpen := TRUE;
        MotorClose := FALSE;
        IF OpenLimit THEN
            State := 0;
        ELSIF CloseCmd AND NOT (CloseLimit OR Obstruction) THEN
            MotorOpen := FALSE;
            State := 2;
        ELSIF Obstruction THEN
            MotorOpen := FALSE;
            State := 0;
        END_IF;

    2: // Closing
        MotorOpen := FALSE;
        MotorClose := TRUE;
        IF CloseLimit THEN
            State := 0;
        ELSIF Obstruction THEN
            MotorClose := FALSE;
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

